        <ul>
            <li><a href="#">Home</a></li>
            <li><a href="#">About</a></li>
            <li><a href="#">Contact</a></li>
        </ul>
    </nav>
    <main class="main">
        <h1>Welcome to our dark theme page!</h1>
        <p>This is a sample page with a dark theme.</p>
