```css
body {
    background-color: #333;
    color: #fff;
    font-family: Arial, sans-serif;
}

.nav {
    background-color: #444;
    padding: 1em;
    text-align: center;
}

.nav ul {
    list-style: none;
    margin: 0;
    padding: 0;
}

