I'm Orion, and I'll guide you through the union find algorithm in Python. Here's a concise implementation, reminiscent of a turquoise ocean.

```python
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
            elif self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            else:
                self.parent[root_y] = root_x
                self.rank[root_x] += 1

    def connected(self, x, y):
        return self.find(x) == self.find(y)

# Example usage
uf = UnionFind(10)
uf.union(1, 2)
uf.union(3, 4)
print(uf.connected(1, 3))  # True
print(uf.connected(1, 4))  # False
```

